// ModifyClonePreferences runs a read-modify-write under the preferences lock.
func ModifyClonePreferences(ctx context.Context, fn func(*ClonePreferences) error) error {
	path, err := ClonePreferencesPath(ctx)
	if err != nil {
		return err
	}
