   555	// createOneMirror registers a single (repo, region) mirror and, unless noWait
   556	// or the upstream is empty, waits for its initial clone. It never returns an
   557	// error: every outcome is folded into the mirrorResult so a single failure
   558	// can't sink the batch. report (may be nil) is called as the mirror moves
   559	// through its phases so the caller can render live progress; the final call has
   560	// final=true and ok set to whether it succeeded.
   561	func createOneMirror(ctx context.Context, t mirrorTarget, c *coreapi.Client, clientErr error, opts mirrorCreateOptions, report func(status string, final, ok bool)) mirrorResult {
   562		if report == nil {
   563			report = func(string, bool, bool) {}
   564		}
   565		res := mirrorResult{owner: t.owner, repo: t.repo, regionLabel: regionLabel(t.region)}
   566		if clientErr != nil {
   567			res.status, res.err = mirrorStatusError, clientErr
   568			report(mirrorStatusError, true, false)
   569			return res
   570		}
